import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

const app = () => request(createApp());
const body = (email = `u-${Date.now()}@example.com`, name = 'Alice') => ({ email, name });

describe('users API', () => {
  it('creates, gets, updates and deletes users', async () => {
    const created = await app().post('/v1/users').send(body());
    expect(created.status).toBe(201); expect(created.headers.location).toMatch(/^\/v1\/users\//);
    expect(created.body.role).toBe('member');
    const id = created.body.id;
    expect((await app().get(`/v1/users/${id}`)).status).toBe(200);
    const patched = await app().patch(`/v1/users/${id}`).send({ name: 'Bob' });
    expect(patched.status).toBe(200); expect(patched.body.name).toBe('Bob');
    expect((await app().delete(`/v1/users/${id}`)).status).toBe(204);
    expect((await app().get(`/v1/users/${id}`)).status).toBe(404);
  });
  it('validates input and missing resources as problem responses', async () => {
    for (const res of [await app().post('/v1/users').send({}), await app().get('/v1/users?limit=0'), await app().get('/v1/users/not-a-uuid'), await app().patch('/v1/users/not-a-uuid').send({}), await app().delete('/v1/users/not-a-uuid')]) {
      expect(res.status).toBeGreaterThanOrEqual(400); expect(res.headers['content-type']).toContain('application/problem+json'); expect(res.body.detail).toBeTruthy();
    }
    const malformed = await app().post('/v1/users').set('Content-Type','application/json').send('{');
    expect(malformed.status).toBe(400);
  });
  it('enforces uniqueness and idempotency', async () => {
    const value = body('same@example.com');
    const first = await app().post('/v1/users').set('Idempotency-Key','k').send(value);
    const replay = await app().post('/v1/users').set('Idempotency-Key','k').send(value);
    expect(replay.status).toBe(201); expect(replay.headers['idempotent-replayed']).toBe('true'); expect(replay.body.id).toBe(first.body.id);
    expect((await app().post('/v1/users').send(value)).status).toBe(409);
    expect((await app().post('/v1/users').set('Idempotency-Key','k').send(body('other@example.com'))).status).toBe(422);
  });
  it('paginates without duplicates', async () => {
    for (let i=0;i<3;i++) await app().post('/v1/users').send(body(`page${i}-${Date.now()}@x.com`));
    const seen: string[] = []; let cursor: string | undefined;
    do { const r = await app().get('/v1/users').query({ limit: 2, cursor }); expect(r.status).toBe(200); seen.push(...r.body.data.map((u: {id:string})=>u.id)); cursor = r.body.nextCursor ?? undefined; } while (cursor);
    expect(new Set(seen).size).toBe(seen.length);
  });
  it('rejects empty patch', async () => { const c=await app().post('/v1/users').send(body()); expect((await app().patch(`/v1/users/${c.body.id}`).send({})).status).toBe(422); });
});

import type { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';

const UserSchema = z.object({ id: z.string().uuid(), email: z.string().email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.string().datetime(), updatedAt: z.string().datetime() });
const CreateSchema = z.object({ email: z.string().email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') }).strict();
const PatchSchema = z.object({ email: z.string().email().optional(), name: z.string().min(1).max(100).optional(), role: z.enum(['admin', 'member']).optional() }).strict();
const IdSchema = z.object({ userId: z.string().uuid() });

type User = z.infer<typeof UserSchema>;

export function registerRoutes(app: Router): void {
  const users = new Map<string, User>();
  const validate = (schema: z.ZodType<unknown>, value: unknown): unknown => { const result = schema.safeParse(value); if (!result.success) throw unprocessable(result.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; ')); return result.data; };
  const get = (req: Request): User => { const { userId } = validate(IdSchema, req.params) as { userId: string }; const user = users.get(userId); if (user === undefined) throw notFound('User not found'); return user; };
  const create = (req: Request, res: Response): void => { const input = validate(CreateSchema, req.body) as z.infer<typeof CreateSchema>; if ([...users.values()].some((u) => u.email === input.email)) throw conflict('email: already exists'); const now = new Date().toISOString(); const user = UserSchema.parse({ ...input, id: crypto.randomUUID(), createdAt: now, updatedAt: now }); users.set(user.id, user); res.location(`/v1/users/${user.id}`).status(201).json(UserSchema.parse(user)); };
  app.post('/v1/users', idempotency(), create);
  app.get('/v1/users', (req: Request, res: Response): void => { const query = validate(CursorQuerySchema, req.query) as z.infer<typeof CursorQuerySchema>; const page = paginate([...users.values()], query, (u) => `${u.createdAt}|${u.id}`); res.json(pageSchema(UserSchema).parse(page)); });
  app.get('/v1/users/:userId', (req, res) => res.json(UserSchema.parse(get(req))));
  app.patch('/v1/users/:userId', idempotency(), (req: Request, res: Response): void => { const old = get(req); const patch = validate(PatchSchema, req.body) as z.infer<typeof PatchSchema>; if (Object.keys(patch).length === 0) throw unprocessable('body: must not be empty'); if (patch.email !== undefined && [...users.values()].some((u) => u.id !== old.id && u.email === patch.email)) throw conflict('email: already exists'); const user = UserSchema.parse({ ...old, ...patch, updatedAt: new Date().toISOString() }); users.set(user.id, user); res.json(UserSchema.parse(user)); });
  app.delete('/v1/users/:userId', (req: Request, res: Response): void => { const user = get(req); users.delete(user.id); res.status(204).send(); });
}

